using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;

namespace MouseTrackerTabajara.Desktop;

public static class ReportQuestionDashboard
{
    private static TextBlock Text(string s,double size=13)=>new(){Text=s,FontSize=size,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(4)};
    private static string N(double? v)=>v?.ToString("0.####",System.Globalization.CultureInfo.InvariantCulture)??"held";
    public static FrameworkElement Build(ReportContext c,ReportContext original,Action<ReportTrial> navigate)
    {
        if(c.Questions is not {} q)return Text("Historical report predates question exports; recompute frozen inputs with compatible code. No group numbers inferred.");
        var summary=new StackPanel();summary.Children.Add(Text("Group overview — equal mice, complete planned repeats",21));summary.Children.Add(Text("Conditional means and observed min–max describe heterogeneity. Phase/day, effective window, units, all held/excluded/missing participants and source-linked extremes stay explicit; no significance or causal memory score."));
        var selector=new ComboBox{ItemsSource=q.Groups.Select(g=>g.Endpoint).Distinct().Order(StringComparer.Ordinal).ToArray(),MinWidth=250,Margin=new Thickness(4),Tag="group-question-endpoint-selector"};summary.Children.Add(selector);var cards=new WrapPanel();summary.Children.Add(cards);var differences=new StackPanel();summary.Children.Add(differences);void Show(){cards.Children.Clear();differences.Children.Clear();var selected=selector.SelectedItem as string;foreach(var group in q.Groups.Where(g=>g.Endpoint==selected).OrderBy(g=>g.Group,StringComparer.Ordinal))
        {var content=new StackPanel{Width=285,Margin=new Thickness(8)};content.Children.Add(Text(group.Group+" · "+group.Endpoint,16));content.Children.Add(Text($"{N(group.Mean)} {group.Unit} · observed {N(group.Minimum)}–{N(group.Maximum)}"));content.Children.Add(Text($"{(group.WindowSeconds.HasValue ? "Effective " + N(group.WindowSeconds) + "s" : group.Mean.HasValue && group.Endpoint is "adjacent speed" or "proximity" && group.Support.Any(s => s.StartsWith("Complete confirmed-mounting training trials:", StringComparison.Ordinal)) ? "Confirmed task durations; no fixed window" : "Effective window held")} · animals expected/included/held/excluded {group.ExpectedAnimals}/{group.IncludedAnimals}/{group.HeldAnimals}/{group.ExcludedAnimals}; trials supported/expected/excluded {group.SupportedTrials}/{group.ExpectedTrials}/{group.ExcludedTrials}. {string.Join(" | ",group.Support)}"));
            var eligible=q.Animals.Where(a=>a.Group==group.Group&&a.Endpoint==group.Endpoint&&a.Value.HasValue&&!a.Excluded).OrderBy(a=>a.Value).ToArray();var plot=new Canvas{Width=265,Height=82,Background=Brushes.White,Tag="group-question-distribution"};var max=Math.Max(.001,q.Animals.Where(a=>a.Endpoint==group.Endpoint&&a.Unit==group.Unit&&a.Value.HasValue&&!a.Excluded).Select(a=>a.Value!.Value).DefaultIfEmpty(1).Max());var rank=0;
            foreach(var animal in eligible){var index=q.Animals.IndexOf(animal);var id=original.Questions!.Animals[index].Animal;var trial=original.Trials.FirstOrDefault(t=>t.Animal==id&&t.VideoId is not null);var dot=new Button{Padding=new Thickness(0),Width=16,Height=16,ToolTip=animal.Animal+" · "+N(animal.Value)+" "+group.Unit+"; source-linked observed extreme, not a significance test"};var circle=new FrameworkElementFactory(typeof(Ellipse));circle.SetValue(Shape.FillProperty,new SolidColorBrush(Color.FromRgb(21,119,149)));circle.SetValue(Shape.StrokeProperty,Brushes.White);circle.SetValue(Shape.StrokeThicknessProperty,1d);dot.Template=new ControlTemplate(typeof(Button)){VisualTree=circle};dot.Click+=(_,_)=>{if(trial is not null)navigate(trial);};Canvas.SetLeft(dot,8+240*animal.Value!.Value/max);Canvas.SetTop(dot,4+rank++%4*16);plot.Children.Add(dot);}content.Children.Add(plot);content.Children.Add(Text("Shared endpoint scale0–"+N(max)+" "+group.Unit+". Click a mouse to inspect source; vertical jitter is display only."));cards.Children.Add(new Border{Child=content,Background=new SolidColorBrush(Color.FromRgb(228,241,247)),CornerRadius=new CornerRadius(8)});}
        foreach(var d in q.Differences.Where(d=>d.Endpoint==selector.SelectedItem as string))differences.Children.Add(Text($"{d.GroupA} minus {d.GroupB} · {d.Endpoint}: {N(d.Difference)} {d.Unit}. {d.Support}"));}selector.SelectionChanged+=(_,_)=>Show();selector.SelectedItem=selector.Items.Contains("adjacent speed")?"adjacent speed":selector.Items.Cast<string>().FirstOrDefault();summary.Children.Add(Text("Publication includes COORD / DIST / PATH / PCOORD / DENSI / AREA RESULT / AREA TIME, group/trial CSV and a pt-BR decimal-comma CSV. Unknowns stay blank; every figure is source/window/units labeled."));return summary;
    }
}
